#include "engine/ai_controller.hpp"
#include "engine/editor.hpp"
#include "engine/editor_play.hpp"
#include <iostream>
#include <limits>
#include <sstream>
#include <iomanip>
using namespace engine;
namespace {
int failures=0;void check(bool b,const char* s){if(!b){++failures;std::cerr<<"FAIL: "<<s<<'\n';}}
template<class F>bool rejects(F fn){try{fn();return false;}catch(const std::exception&){return true;}}
std::shared_ptr<const StateMachineDefinition> graph(bool cycle=true){StateMachineData d;d.states={{0,"Move","move",{0,0}},{1,"Idle","idle",{300,0}}};if(cycle)d.transitions={{0,0,1,"always",.2},{1,1,0,"always",.2}};return StateMachineDefinition::create(std::move(d));}
CharacterMotorComponent& motor(Actor& a){CharacterMotorSettings s;s.collisionAware=false;return a.addComponent<CharacterMotorComponent>("Motor",s);}
void runtime(){Scene scene;auto& a=scene.spawn("Agent");auto& m=motor(a);auto settings=AiControllerSettings::defaults(graph(),*AiBindingRegistry::builtins());auto& ai=a.addComponent<AiControllerComponent>("AI",settings);scene.fixedUpdate(.1);
    check(a.transform.position.x>.09f&&ai.status()==StateMachineStatus::Running,"Controller executes before an earlier-inserted free motor");scene.fixedUpdate(.1);check(ai.currentState()==1&&m.movementCommand().velocity.x==0&&ai.transitions().size()==1,"Transition exits clear movement and record history");
    const auto p=a.transform.position.x;ai.enabled=false;scene.fixedUpdate(.1);check(ai.status()==StateMachineStatus::Stopped&&a.transform.position.x==p,"Disable stops persistent commands");ai.enabled=true;scene.fixedUpdate(.1);check(ai.status()==StateMachineStatus::Stopped,"Re-enable requires explicit restart");ai.restart();scene.fixedUpdate(.1);check(a.transform.position.x>p,"Explicit restart starts a fresh agent instance");
    auto bad=settings;bad.states[0].parameters["velocity"]=true;check(rejects([&]{ai.configure(bad);})&&ai.status()==StateMachineStatus::Running,"Wrong parameter type rejects without interrupting valid runtime");bad=settings;bad.states[0].key="missing";check(rejects([&]{ai.configure(bad);}),"Unregistered behavior rejects");
    for(int i=0;i<200;++i)scene.fixedUpdate(.1);check(ai.transitions().size()==32,"Live transition history stays bounded");
    auto& b=scene.spawn("Second");motor(b);auto& second=b.addComponent<AiControllerComponent>("AI",settings);scene.fixedUpdate(.1);check(second.transitions().empty()&&ai.transitions().size()==32,"Instances own separate timers and transition logs");
    ai.destroy();scene.fixedUpdate(.1);check(m.movementCommand().velocity.x==0,"Deferred controller removal stops its motor");
}
void persistence(){Scene scene;auto& a=scene.spawn("Agent");motor(a);auto s=AiControllerSettings::defaults(graph(false),*AiBindingRegistry::builtins());auto& ai=a.addComponent<AiControllerComponent>("AI",s);scene.synchronize();auto id=ai.savedId();auto codecs=aiControllerCodecs();const auto before=SceneArchive::save(scene,{}, {},{}, {},codecs);auto doc=SceneArchive::load(before,{},codecs);auto* restored=dynamic_cast<AiControllerComponent*>(doc.scene->findSavedNode(id));check(restored&&restored->status()==StateMachineStatus::Idle,"Scene codec restores configuration with fresh runtime");check(SceneArchive::save(*doc.scene,{}, {},{}, {},codecs)==before,"Controller scene archive roundtrip retains canonical assignment/configuration");check(rejects([&]{SceneArchive::load(before);}),"Unknown custom codecs reject rather than silently dropping AI");
    EditorPlaySession play;play.start(scene,{}, {},codecs);auto* live=dynamic_cast<AiControllerComponent*>(play.scene()->findSavedNode(id));check(live&&live!=&ai,"Play recreates controller with fresh scene handles");play.advance(0);play.advance(.1);check(live->status()==StateMachineStatus::Running&&ai.status()==StateMachineStatus::Idle,"Only Play instance advances");play.stop();check(SceneArchive::save(scene,{}, {},{}, {},codecs)==before,"Stop preserves source configuration and bytes");
    auto nearGraph=graph(false)->data();nearGraph.transitions={{0,0,1,"near",0}};s=AiControllerSettings::defaults(StateMachineDefinition::create(nearGraph),*AiBindingRegistry::builtins());s.conditions["near"].parameters["target"]=a.savedId();ai.configure(s);auto good=SceneArchive::save(scene,{}, {},{}, {},codecs);auto reloaded=SceneArchive::load(good,{},codecs);reloaded.scene->fixedUpdate(.1);check(dynamic_cast<AiControllerComponent*>(reloaded.scene->findSavedNode(id))->currentState()==1,"Saved actor references resolve in reconstructed scene");
    s.conditions["near"].parameters["target"]=std::string("missing-actor");check(rejects([&]{ai.configure(s);}),"Missing target rejects without partial configuration");
}
void blackboard(){
    auto registry=AiBindingRegistry::builtins();auto d=graph(false)->data();d.transitions={{0,0,1,"seen",.2},{1,1,0,"lost",0}};
    d.blackboard={{"targetVisible",AiParameterType::Boolean,false},{"health",AiParameterType::Number,100.0,0,100},{"velocity",AiParameterType::Vector,Vec3{1,0,0},-100,100},{"target",AiParameterType::Actor,std::string{}}};
    auto def=StateMachineDefinition::create(d);AiControllerSettings settings;settings.graph=def;settings.states={{0,registry->defaults("move")},{1,registry->defaults("idle")}};settings.states[0].sources["velocity"]="velocity";settings.conditions={{"seen",registry->defaults("flag",true)},{"lost",registry->defaults("not-flag",true)}};settings.conditions["seen"].sources["value"]="targetVisible";settings.conditions["lost"].sources["value"]="targetVisible";
    Scene scene;auto& a=scene.spawn("Agent");motor(a);auto& ai=a.addComponent<AiControllerComponent>("AI",settings);auto& b=scene.spawn("Other");motor(b);auto& other=b.addComponent<AiControllerComponent>("AI",settings);scene.fixedUpdate(.1);auto seconds=ai.stateSeconds();
    ai.setBlackboard({{"targetVisible",true},{"velocity",Vec3{3,0,0}},{"health",50.0},{"target",b.savedId()}});
    check(ai.stateSeconds()==seconds&&ai.currentState()==0&&ai.transitions().empty(),"Live patch preserves state, timer and transition log");check(!std::get<bool>(other.blackboardValue("targetVisible")),"Shared graph instances have independent values");
    check(rejects([&]{ai.setBlackboard({{"health",-1.0},{"targetVisible",false}});})&&std::get<bool>(ai.blackboardValue("targetVisible")),"Invalid multi-field patch publishes no partial values");
    check(rejects([&]{ai.setBlackboard({{"health",true}});})&&rejects([&]{ai.setBlackboard({{"unknown",false}});}),"Wrong types and unknown fields reject");
    check(rejects([&]{ai.setBlackboard({{"velocity",Vec3{std::numeric_limits<float>::infinity(),0,0}}});})&&rejects([&]{ai.setBlackboard({{"target",std::string("absent")}});}),"Nonfinite values and nonexistent actor writes reject");
    scene.fixedUpdate(.1);check(ai.currentState()==1&&ai.transitions().back().condition=="seen"&&other.currentState()==0,"Live condition reads resolved value and records transition reason");
    ai.setBlackboard({{"targetVisible",false}});scene.fixedUpdate(.1);scene.fixedUpdate(.1);check(a.transform.position.x>.39f,"Live vector drives behavior without configure");
    auto bad=settings;bad.conditions["seen"].sources["value"]="health";auto retained=AiControllerArchive::save(ai.settings());check(rejects([&]{ai.configure(bad);})&&AiControllerArchive::save(ai.settings())==retained,"Incompatible source rejects atomically");bad=settings;bad.states[0].sources["typo"]="velocity";check(rejects([&]{ai.configure(bad);}),"Unknown source parameter rejects");bad=settings;auto badGraph=d;badGraph.blackboard[2].maximum=101;bad.graph=StateMachineDefinition::create(badGraph);check(rejects([&]{ai.configure(bad);}),"Source range must fit every consuming parameter");
    auto payload=AiControllerArchive::save(settings);check(AiControllerArchive::save(AiControllerArchive::load(payload,*registry))==payload,"Schema and source bindings roundtrip exactly");
    auto codecs=aiControllerCodecs();auto bytes=SceneArchive::save(scene,{}, {},{}, {},codecs);auto doc=SceneArchive::load(bytes,{},codecs);auto* restored=dynamic_cast<AiControllerComponent*>(doc.scene->findSavedNode(ai.savedId()));check(restored&&std::get<double>(restored->blackboardValue("health"))==100&&std::get<std::string>(restored->blackboardValue("target")).empty(),"Scene reload uses defaults rather than transient values");
    auto target=b.id();b.destroy();scene.fixedUpdate(.1);check(!scene.findActor(target)&&!ai.resolveActor(std::get<std::string>(ai.blackboardValue("target"))),"Destroyed live target resolves null safely");ai.restart();check(std::get<double>(ai.blackboardValue("health"))==50,"Explicit restart preserves gameplay inputs");
    Scene sensing;auto& observer=sensing.spawn("Observer");motor(observer);auto& targetActor=sensing.spawn("Target");targetActor.transform.position={10,0,0};auto nearData=graph(false)->data();nearData.transitions={{0,0,1,"near",0}};nearData.blackboard={{"target",AiParameterType::Actor,std::string{}},{"distance",AiParameterType::Number,1.0,0,100}};auto nearSettings=AiControllerSettings::defaults(StateMachineDefinition::create(nearData),*registry);nearSettings.conditions["near"].sources={{"target","target"},{"distance","distance"}};auto& sensor=observer.addComponent<AiControllerComponent>("Sensor",nearSettings);sensor.setBlackboard({{"target",targetActor.savedId()}});sensing.fixedUpdate(.1);check(sensor.currentState()==0,"Actor and numeric sources resolve against live target position");sensor.setBlackboard({{"distance",20.0}});sensing.fixedUpdate(.1);check(sensor.currentState()==1,"Numeric live input changes an actor-distance guard");sensor.restart();targetActor.destroy();sensing.fixedUpdate(.1);check(sensor.currentState()==0&&sensor.error().empty(),"Removed actor source makes near false without invalidating runtime");
    Scene grounded;auto& groundedActor=grounded.spawn("Grounded");groundedActor.addComponent<CharacterMotorComponent>();auto& groundedAI=groundedActor.addComponent<AiControllerComponent>("AI",settings);check(rejects([&]{groundedAI.setBlackboard({{"targetVisible",true},{"velocity",Vec3{1,2,0}}});})&&!std::get<bool>(groundedAI.blackboardValue("targetVisible")),"Live movement constraints reject the complete patch");
    auto duplicate=d;duplicate.blackboard.push_back(duplicate.blackboard[0]);check(rejects([&]{StateMachineDefinition::create(duplicate);}),"Duplicate blackboard fields reject");duplicate=d;duplicate.blackboard.resize(65,d.blackboard[0]);check(rejects([&]{StateMachineDefinition::create(duplicate);}),"Blackboard field capacity is bounded");
    auto legacy=StateMachineArchive::load("WEAI 1\n\"Legacy\" 0 1 0\n0 \"Idle\" \"idle\" 0 0\n");check(legacy->data().blackboard.empty(),"Version-one graph files remain readable");
    auto oldPayload=std::string("AIC 1\n");std::ostringstream out;out<<std::quoted("WEAI 1\n\"Legacy\" 0 1 0\n0 \"Idle\" \"idle\" 0 0\n");oldPayload+=out.str()+"\n1 0\n0 \"idle\" 0\n";check(AiControllerArchive::load(oldPayload,*registry).graph->data().blackboard.empty(),"Version-one controller payloads remain readable");
}

void hierarchyController(){
    StateMachineData data;data.name="Actor hierarchy";data.states={{0,"Alive","idle",{}, {},1},{1,"Patrol","move",{},0,{}},{2,"Combat","idle",{},0,3},{3,"Chase","move",{},2,{}},{4,"Dead","idle",{}}};data.transitions={{0,0,4,"flag",0},{1,1,2,"always",.2}};data.blackboard={{"dead",AiParameterType::Boolean,false}};auto settings=AiControllerSettings::defaults(StateMachineDefinition::create(data),*AiBindingRegistry::builtins());settings.conditions["flag"].sources["value"]="dead";
    Scene scene;auto& actor=scene.spawn("Agent");auto& m=motor(actor);auto& ai=actor.addComponent<AiControllerComponent>("AI",settings);scene.fixedUpdate(.1);check(ai.currentState()==1&&ai.activePath().size()==2&&ai.transitions().empty(),"Parent entries do not create spurious controller transitions");scene.fixedUpdate(.1);check(ai.currentState()==3&&ai.activePath().size()==3&&ai.transitions().size()==1&&ai.transitions()[0].transitionId==1,"Transition to nested group records one leaf-to-leaf edge");
    ai.setBlackboard({{"dead",true}});scene.fixedUpdate(.1);check(ai.currentState()==4&&ai.activePath().size()==1&&m.movementCommand().velocity.x==0&&ai.transitions().back().source==0,"Ancestor interrupt cancels persistent child movement before motor tick");
    auto codecs=aiControllerCodecs();auto bytes=SceneArchive::save(scene,{}, {},{}, {},codecs);auto loaded=SceneArchive::load(bytes,{},codecs);auto* restored=dynamic_cast<AiControllerComponent*>(loaded.scene->findSavedNode(ai.savedId()));check(restored&&restored->settings().graph->state(3).parent==2&&restored->transitions().empty(),"Scene roundtrip retains hierarchy with fresh runtime");EditorPlaySession play;play.start(scene,{}, {},codecs);auto* live=dynamic_cast<AiControllerComponent*>(play.scene()->findSavedNode(ai.savedId()));play.advance(0);play.advance(.1);check(live&&live->activePath().size()==2&&live->currentState()==1&&!std::get<bool>(live->blackboardValue("dead")),"Play reconstructs nested entry and independent default inputs");play.stop();
    ai.restart();scene.fixedUpdate(.1);ai.enabled=false;scene.fixedUpdate(.1);check(ai.activePath().empty()&&ai.status()==StateMachineStatus::Stopped&&m.movementCommand().velocity.x==0,"Disable unwinds complete hierarchical controller");
}

void eventController(){
    auto builtin=AiBindingRegistry::builtins();auto behaviors=builtin->behaviors();std::optional<AiEventScope> completion;
    behaviors.push_back({"investigate",{},false,[&](AiControllerComponent& c,const AiBinding&,double){const auto* e=c.currentEvent();if(!e||e->key!="HeardNoise")throw std::runtime_error("Missing triggering payload");c.setBlackboard({{"lastSeen",e->parameters.at("position")}});completion=c.eventScope(1);},{},{}});
    auto registry=AiBindingRegistry::create(std::move(behaviors),builtin->conditions());StateMachineData d;d.states={{0,"Idle","idle",{}},{1,"Investigate","investigate",{}}};d.transitions={{0,0,1,"always",0,"HeardNoise"},{1,1,0,"always",0,"AnimationFinished"}};d.blackboard={{"lastSeen",AiParameterType::Vector,Vec3{},-100,100}};d.events={{"HeardNoise",{{"position",AiParameterType::Vector,Vec3{},-100,100},{"target",AiParameterType::Actor,std::string{}},{"urgent",AiParameterType::Boolean,false},{"confidence",AiParameterType::Number,1.0,0,1}}},{"AnimationFinished",{}}};auto settings=AiControllerSettings::defaults(StateMachineDefinition::create(d),*registry);
    Scene scene;auto& a=scene.spawn("Listener");auto& target=scene.spawn("Target");auto& ai=a.addComponent<AiControllerComponent>("Events",settings,registry);AiEvent heard{"HeardNoise",{{"position",Vec3{4,0,2}},{"target",target.savedId()},{"urgent",true},{"confidence",.75}}};auto codecs=aiControllerCodecs(registry);auto bytes=SceneArchive::save(scene,{}, {},{}, {},codecs);check(ai.postEvent(heard)&&ai.pendingEvents()==1,"Controller queues validated typed gameplay inputs");check(SceneArchive::save(scene,{}, {},{}, {},codecs)==bytes,"Transient event queues/history never change scene configuration bytes");
    EditorPlaySession play;play.start(scene,{}, {},codecs);auto* live=dynamic_cast<AiControllerComponent*>(play.scene()->findSavedNode(ai.savedId()));play.advance(0);play.advance(.1);check(live&&live->currentState()==0&&live->pendingEvents()==0&&live->eventHistory().empty(),"Play reconstructs an independent empty event queue");play.stop();scene.fixedUpdate(.1);check(ai.currentState()==1&&std::get<Vec3>(ai.blackboardValue("lastSeen")).x==4&&ai.transitions().back().event=="HeardNoise"&&ai.transitions().back().eventSequence!=0,"Behavior reads event payload and transition log correlates consumed occurrence");check(completion&&ai.postEvent({"AnimationFinished",{}},completion),"Application captures activation token on event-driven state entry");scene.fixedUpdate(.1);check(ai.currentState()==0&&!ai.postEvent({"AnimationFinished",{}},completion),"Completed animation token cannot trigger a later activation");
    heard.parameters["target"]=std::string("missing-actor");const auto count=ai.pendingEvents();check(rejects([&]{ai.postEvent(heard);})&&ai.pendingEvents()==count,"Missing payload actor rejects before queue mutation");heard.parameters["target"]=target.savedId();ai.postEvent(heard);ai.enabled=false;scene.fixedUpdate(.1);check(ai.pendingEvents()==0&&ai.status()==StateMachineStatus::Stopped,"Controller disable cancels pending occurrences");ai.enabled=true;ai.restart();ai.postEvent(heard);ai.configure(settings);check(ai.pendingEvents()==0&&ai.eventHistory().empty(),"Configuration replacement starts a fresh event runtime");
    auto guarded=builtin->behaviors();guarded[0].update=[](AiControllerComponent& c,const AiBinding&,double){c.configure(c.settings());};auto callbacks=AiBindingRegistry::create(guarded,builtin->conditions());auto idle=graph(false)->data();idle.states={{0,"Idle","idle",{}}};idle.transitions.clear();auto& reentrant=scene.spawn("Reentrant");auto& guard=reentrant.addComponent<AiControllerComponent>("AI",AiControllerSettings::defaults(StateMachineDefinition::create(idle),*callbacks),callbacks);scene.fixedUpdate(.1);check(!guard.error().empty()&&guard.status()==StateMachineStatus::Stopped,"Callback configuration reentry rejects without deleting an executing runtime");
}

void editor(){Scene scene;auto& actor=scene.spawn("Editable agent");auto id=actor.savedId();EditorSession edit(scene);edit.select(id);auto settings=AiControllerSettings::defaults(graph(),*AiBindingRegistry::builtins());check(rejects([&]{edit.setAiController(settings);})&&!actor.hasComponent<AiControllerComponent>()&&edit.undoCount()==0,"Missing motor assignment fails atomically without history");motor(actor);scene.synchronize();check(edit.setAiController(settings)&&actor.hasComponent<AiControllerComponent>(),"Actor assignment creates controller through editor history");check(edit.undo()&&!actor.hasComponent<AiControllerComponent>()&&edit.redo(),"Undo/redo recreates exact controller assignment");auto* ai=edit.selectedAiController();auto next=settings;next.states[0].parameters["velocity"]=Vec3{2,0,0};check(edit.setAiController(next)&&std::get<Vec3>(ai->settings().states.at(0).parameters.at("velocity")).x==2,"Configuration edits publish through scene history");check(edit.undo()&&std::get<Vec3>(ai->settings().states.at(0).parameters.at("velocity")).x==1,"Undo restores previous typed parameters");
    auto bytes=AiControllerArchive::save(settings);check(AiControllerArchive::save(AiControllerArchive::load(bytes,*AiBindingRegistry::builtins()))==bytes,"Controller payload roundtrip is exact");check(rejects([&]{AiControllerArchive::load(bytes+"garbage",*AiBindingRegistry::builtins());}),"Malformed controller payload rejects");
}
}
int main(){runtime();persistence();blackboard();hierarchyController();eventController();editor();if(failures)return 1;std::cout<<"Actor AI controller contracts passed\n";}
